head.script:
scwin.onpageload = function () {
    let req = "<script>alert('XSS')</scr" + "ipt>반품 요청";
    dlt_a.setJSON([{ "colA" : req, "colB" : req }]);
};

// escapeFormatter : script 태그 제거
scwin.fmtEscape = function (data, rowIndex, colIndex) {
    let reScript = new RegExp("<script.*?</scr" + "ipt>", "gi");
    return String(data).replace(reScript, "");
};

// A, B Column 의 화면 표시값 / getCellDisplayData 출력
scwin.btn_get_onclick = function (e) {
    let arr = [["[A] ", "colA"], ["[B] ", "colB"]];
    for (let i = 0; i < arr.length; i++) {
        let td = document.querySelector("td[id*='" + grd_a.id + "_cell_0_" + grd_a.getColumnIndex(arr[i][1]) + "']");
        let screen = td ? td.textContent : "";
        scwin.setReturnValue(arr[i][0] + "화면 표시값 '" + screen + "' / getCellDisplayData '" + grd_a.getCellDisplayData(0, arr[i][1]) + "'");
    }
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
